<template><AppShell :title="item?.title||'活动详情'" back><StateView :loading="loading" :error="error" :count="item?1:0" @retry="load" /><view v-if="item&&!loading&&!error" class="article-page"><image class="article-cover" :src="contentImage(item.cover)" mode="widthFix" /><view class="pad"><text class="article-title">{{item.title}}</text><view class="row between section"><text class="muted tiny">{{date(item.startsAt)}} — {{date(item.endsAt)}}</text><text class="tag">{{phases[item.phase]}}</text></view><text v-if="item.summary" class="article-summary">{{item.summary}}</text><text class="article-body">{{item.body}}</text></view><image v-for="pic in details" :key="pic" class="article-detail" :src="contentImage(pic)" mode="widthFix" @click="preview(pic)" /><view v-if="item.rewardActivityId" class="pad"><button class="ui-button btn wide" :disabled="!item.rewardAvailable" @click="go('rewards/activity',{id:item.rewardActivityId})">{{item.rewardAvailable?'参加积分转盘':item.phase==='ENDED'?'活动已结束':'转盘暂未开放'}}</button></view></view></AppShell></template>
<script setup>
import {ref,computed} from 'vue';import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,go,date,images} from '../../lib/api';import {contentImage} from '../../lib/content'
const id=ref(''),item=ref(null),loading=ref(false),error=ref(''),phases={UPCOMING:'即将开始',ONGOING:'进行中',ENDED:'已结束'},details=computed(()=>images(item.value?.detailImages));let generation=0
onLoad(q=>id.value=q.id);onShow(load);onUnload(()=>generation++)
async function load(){const v=++generation;loading.value=true;error.value='';item.value=null;try{const r=await request('/boost/content/activities/'+id.value);if(v===generation)item.value=r}catch(e){if(v===generation)error.value=e.message}finally{if(v===generation)loading.value=false}}
function preview(pic){uni.previewImage({urls:details.value.map(contentImage),current:contentImage(pic)})}
</script>
<style scoped>.article-page{background:#fff;min-height:calc(100vh - 62px)}.article-cover,.article-detail{display:block;width:100%}.article-title{display:block;font-size:24px;line-height:1.4;font-weight:750}.article-summary{display:block;margin-top:20px;color:#777}.article-body{display:block;white-space:pre-wrap;line-height:1.9;margin-top:20px;font-size:15px}.article-detail{margin-bottom:4px}</style>
